blocs/feedback/basic-toast/style.css.content:
:host {
    --basic-toast-background: var(--integration-basic-blocs-surface-background, var(--bg-surface, Canvas));
    --basic-toast-border: var(--integration-basic-blocs-surface-border, var(--border-default, color-mix(in srgb, currentColor 16%, transparent)));
    --basic-toast-color: var(--integration-basic-blocs-surface-text, var(--text-main, CanvasText));
    --basic-toast-close-color: var(--basic-toast-color);
    --basic-toast-padding: .75rem .875rem;
    --basic-toast-radius: var(--integration-basic-blocs-surface-radius, var(--radius-md, .5rem));
    --basic-toast-shadow: none;
    --basic-toast-width: max-content;

    position: fixed;
    z-index: 10000;
    top: 1.5rem;
    right: 1.5rem;
    display: flex;
    box-sizing: border-box;
    width: var(--basic-toast-width);
    min-width: min(18rem, calc(100vw - 2rem));
    max-width: min(26rem, calc(100vw - 2rem));
    align-items: flex-start;
    gap: .625rem;
    padding: var(--basic-toast-padding);
    border: 1px solid var(--basic-toast-border);
    border-radius: var(--basic-toast-radius);
    background: var(--basic-toast-background);
    color: var(--basic-toast-color);
    box-shadow: var(--basic-toast-shadow);
    font: inherit;
    line-height: 1.4;
    animation: basic-toast-in 180ms ease-out;
}

:host([hidden]) {
    display: none !important;
}

:host([position="top-left"]) {
    right: auto;
    left: 1.5rem;
}

:host([position="bottom-right"]) {
    top: auto;
    bottom: 1.5rem;
}

:host([position="bottom-left"]) {
    top: auto;
    right: auto;
    bottom: 1.5rem;
    left: 1.5rem;
}

:host([width="sm"]) { --basic-toast-width: min(18rem, calc(100vw - 2rem)); }
:host([width="md"]) { --basic-toast-width: min(22rem, calc(100vw - 2rem)); }
:host([width="lg"]) { --basic-toast-width: min(26rem, calc(100vw - 2rem)); }
:host([width="full"]) { --basic-toast-width: calc(100vw - 3rem); }

:host([density="compact"]) { --basic-toast-padding: .5rem .625rem; }
:host([density="spacious"]) { --basic-toast-padding: 1rem 1.125rem; }

:host([radius="none"]) { --basic-toast-radius: 0; }
:host([radius="sm"]) { --basic-toast-radius: var(--radius-sm, .25rem); }
:host([radius="md"]) { --basic-toast-radius: var(--radius-md, .5rem); }
:host([radius="lg"]) { --basic-toast-radius: var(--radius-lg, 1rem); }
:host([radius="pill"]) { --basic-toast-radius: 999px; }

:host([shadow="sm"]) { --basic-toast-shadow: var(--shadow-sm, 0 .25rem .75rem color-mix(in srgb, CanvasText 10%, transparent)); }
:host([shadow="md"]) { --basic-toast-shadow: var(--integration-basic-blocs-elevated-shadow, var(--shadow-md, 0 .5rem 1.25rem color-mix(in srgb, CanvasText 14%, transparent))); }
:host([shadow="lg"]) { --basic-toast-shadow: var(--shadow-lg, 0 .75rem 2rem color-mix(in srgb, CanvasText 18%, transparent)); }

.icon {
    flex: 0 0 auto;
    line-height: 1;
}

:host(:not(:has([slot="icon"]))) .icon {
    display: none;
}

::slotted([slot="icon"]) {
    display: block;
    width: 1.25rem;
    height: 1.25rem;
}

.message {
    flex: 1;
    min-width: 0;
    overflow-wrap: anywhere;
}

button {
    flex: 0 0 auto;
    margin: -.25rem -.25rem 0 0;
    padding: .125rem .25rem;
    border: 0;
    background: transparent;
    color: var(--basic-toast-close-color);
    cursor: pointer;
    font: inherit;
    font-size: 1.25rem;
    line-height: 1;
    opacity: .6;
}

button:hover { opacity: 1; }
button:focus-visible {
    outline: 2px solid var(--integration-basic-blocs-focus-color, currentColor);
    outline-offset: 2px;
}

:host([leaving]) {
    pointer-events: none;
    animation: basic-toast-out 180ms ease-in forwards;
}

[hidden] { display: none !important; }

@keyframes basic-toast-in {
    from { opacity: 0; transform: translateY(-.5rem); }
    to { opacity: 1; transform: translateY(0); }
}

@keyframes basic-toast-out {
    from { opacity: 1; transform: translateY(0); }
    to { opacity: 0; transform: translateY(-.5rem); }
}

@media (max-width: 32rem) {
    :host,
    :host([position]) {
        right: 1rem;
        left: 1rem;
        width: auto;
        min-width: 0;
        max-width: none;
    }

    :host([position="top-left"]),
    :host([position="top-right"]) {
        top: 1rem;
    }

    :host([position="bottom-left"]),
    :host([position="bottom-right"]) {
        top: auto;
        bottom: 1rem;
    }
}

@media (prefers-reduced-motion: reduce) {
    :host,
    :host([leaving]) { animation: none; }
}

