                    color: var(--cms-chip-color, var(--integration-basic-blocs-field-text, var(--text-main, inherit)));
                    font: inherit;
                    cursor: pointer;
                }

                :host([selected]) button {
                    border-color: var(--cms-chip-selected-border, var(--integration-basic-blocs-action-background, var(--primary-base, CanvasText)));
                    background: var(--cms-chip-selected-background, var(--integration-basic-blocs-action-background, var(--primary-base, CanvasText)));
                    color: var(--cms-chip-selected-color, var(--cms-chip-color, var(--integration-basic-blocs-action-text, var(--primary-foreground, var(--primary-contrasted, Canvas)))));
                }

                button:focus-visible {
                    outline: 2px solid var(--cms-focus-color, var(--integration-basic-blocs-focus-color, var(--primary-base, CanvasText)));
